/** The four measure columns of the `measurements` table. */
export type Field = 'temp_inside' | 'hum_inside' | 'temp_outside' | 'hum_outside';

/** Time aggregation used by api/series.php. */
export type Bucket = '5m' | '1h' | '1d';

/** Theme can follow the operating system ("auto") or be pinned. */
export type ThemeMode = 'light' | 'dark' | 'auto';

/** Which y scale a series belongs to. Temperature is °C, humidity is %. */
export type AxisId = 'temp' | 'hum';

/** Static description of one measure column. */
export interface FieldMeta {
  key: Field;
  /** Short German label for the UI. */
  label: string;
  unit: string;
  axis: AxisId;
  /** Number of decimals used when formatting a value. */
  decimals: number;
}

export const FIELDS: readonly FieldMeta[] = [
  { key: 'temp_inside', label: 'Temperatur innen', unit: '°C', axis: 'temp', decimals: 1 },
  { key: 'hum_inside', label: 'Luftfeuchte innen', unit: '%', axis: 'hum', decimals: 0 },
  { key: 'temp_outside', label: 'Temperatur außen', unit: '°C', axis: 'temp', decimals: 1 },
  { key: 'hum_outside', label: 'Luftfeuchte außen', unit: '%', axis: 'hum', decimals: 0 },
];

/** Lookup helper: metadata for a field key. */
export function fieldMeta(key: Field): FieldMeta {
  const meta = FIELDS.find((f) => f.key === key);
  if (!meta) throw new Error(`unknown field: ${key}`);
  return meta;
}

/**
 * How the time window of a preset is derived.
 *
 * `year` covers one complete calendar year, `currentYear` runs from January 1st
 * of the current year up to now.
 */
export type PresetRange =
  | { kind: 'hours'; hours: number }
  | { kind: 'year'; year: number }
  | { kind: 'currentYear' }
  | { kind: 'all' };

/** One preset button above the chart. */
export interface Preset {
  id: string;
  label: string;
  range: PresetRange;
  bucket: Bucket;
  fields: readonly Field[];
}

/** One row of api/years.php. */
export interface YearInfo {
  year: number;
  rows: number;
}

/** Response of api/years.php - which calendar years hold data. */
export interface YearsResponse {
  /** Calendar year the database server considers current. */
  current_year: number;
  years: YearInfo[];
}

/** Response of api/current.php - the newest row of the table. */
export interface CurrentResponse {
  measured_at: string | null;
  temp_inside: number | null;
  hum_inside: number | null;
  temp_outside: number | null;
  hum_outside: number | null;
}

/** min / avg / max of one field over the requested window. */
export interface FieldStats {
  min: number | null;
  avg: number | null;
  max: number | null;
}

/** Response of api/stats.php. */
export interface StatsResponse {
  hours: number;
  rows: number;
  stats: Record<Field, FieldStats>;
}

/** One aggregated point of the time series. */
export type SeriesPoint = { t: number } & Partial<Record<Field, number | null>>;

/** Response of api/series.php. */
export interface SeriesResponse {
  fields: Field[];
  bucket: Bucket;
  points: SeriesPoint[];
}

/** Generic error body returned by the API on failure. */
export interface ApiErrorResponse {
  error: string;
}
